//! Fixture generated by actual PostgreSQL 17.9 pg_dump over native PGlite 17.5.
//! Its generated guard key also occurs in real row and function literals.
use anyhow::Result;
use cantrip_server::{database::Database, database_transfer::prepare_sql};

#[tokio::test]
async fn native_dump_normalization_preserves_same_key_literals_and_null_types() -> Result<()> {
    let raw = include_str!("fixtures/native-pg17-dump.sql");
    assert_eq!(
        raw.matches("\\restrict CantripNativeDumpProbe42").count(),
        3
    );
    assert_eq!(
        raw.matches("\\unrestrict CantripNativeDumpProbe42").count(),
        3
    );
    let root = tempfile::tempdir()?;
    let database = Database::pglite(&root.path().join("database")).await?;
    for sql in [
        raw.to_owned(),
        raw.replacen(
            "\\restrict CantripNativeDumpProbe42\n",
            "\\restrict CantripNativeDumpProbe42\r\n",
            1,
        )
        .trim_end()
        .strip_suffix("\\unrestrict CantripNativeDumpProbe42")
        .unwrap()
        .to_owned()
            + "\\unrestrict CantripNativeDumpProbe42\r\n",
    ] {
        let prepared = prepare_sql(sql)?;
        assert_eq!(prepared.guards_removed, 2);
        assert!(prepared.portable_transaction_timeout);
        assert_eq!(
            prepared
                .sql
                .matches("\\restrict CantripNativeDumpProbe42")
                .count(),
            2
        );
        assert_eq!(
            prepared
                .sql
                .matches("\\unrestrict CantripNativeDumpProbe42")
                .count(),
            2
        );
        database.execute(&prepared.sql).await?;
        let rows=database.query("SELECT id::text,value,public.native_probe(),metadata IS NULL,jsonb_typeof(metadata),precise::text,encode(bytes,'hex') FROM public.native_probe ORDER BY id",&[]).await?;
        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].get::<String>(0)?, "2");
        assert!(!rows[0].get::<bool>(3)?);
        assert_eq!(rows[0].get::<Option<String>>(4)?, Some("null".into()));
        assert_eq!(rows[1].get::<String>(0)?, "9007199254740993");
        let literal = "before\n\\restrict CantripNativeDumpProbe42\nmiddle\n\\unrestrict CantripNativeDumpProbe42\nafter 🦀";
        assert_eq!(rows[1].get::<String>(1)?, literal);
        assert_eq!(rows[1].get::<String>(2)?, literal);
        assert!(rows[1].get::<bool>(3)?);
        assert_eq!(rows[1].get::<Option<String>>(4)?, None);
        assert_eq!(
            rows[1].get::<String>(5)?,
            "123456789012345678901234567890.12345"
        );
        assert_eq!(rows[1].get::<String>(6)?, "00ff");
        database
            .execute("DROP TABLE public.native_probe; DROP FUNCTION public.native_probe()")
            .await?;
    }
    database.close().await?;
    Ok(())
}
